import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Rag","description":"Rag reference documentation","frontmatter":{"title":"Rag","description":"Rag reference documentation"},"headers":[],"relativePath":"knowledge/rag.md","filePath":"knowledge/rag.md","lastUpdated":1784485118000}'),i={name:"knowledge/rag.md"};function o(s,e,l,c,d,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="rag" tabindex="-1">Rag <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;Rag&quot;">​</a></h1><h1 id="retrieval-augmented-generation-rag-—-knowledge-base" tabindex="-1">Retrieval-Augmented Generation (RAG) — Knowledge Base <a class="header-anchor" href="#retrieval-augmented-generation-rag-—-knowledge-base" aria-label="Permalink to &quot;Retrieval-Augmented Generation (RAG) — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>RAG combines information retrieval with language model generation. It retrieves relevant documents from a knowledge base and provides them as context to an LLM, enabling accurate, grounded responses without retraining. This knowledge base covers chunking, retrieval, and generation strategies for production RAG systems.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="rag-pipeline" tabindex="-1">RAG Pipeline <a class="header-anchor" href="#rag-pipeline" aria-label="Permalink to &quot;RAG Pipeline&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Query → Query Processing → Retrieval → Reranking → Context Assembly → LLM Generation → Response</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Query processing</strong> — Reformulate, expand, or decompose the user&#39;s query for better retrieval.</p><p><strong>Retrieval</strong> — Search the knowledge base for relevant documents using keyword, semantic, or hybrid search.</p><p><strong>Reranking</strong> — Re-score retrieved documents by relevance to refine the top results.</p><p><strong>Context assembly</strong> — Format and truncate retrieved documents to fit the LLM&#39;s context window.</p><p><strong>Generation</strong> — LLM generates a response grounded in the provided context.</p><h3 id="chunking-strategies" tabindex="-1">Chunking Strategies <a class="header-anchor" href="#chunking-strategies" aria-label="Permalink to &quot;Chunking Strategies&quot;">​</a></h3><p><strong>Fixed-size chunking</strong> — Split documents into chunks of fixed token count (e.g., 512 tokens). Simple but may break semantic units.</p><p><strong>Semantic chunking</strong> — Split at natural boundaries (paragraphs, sections, topics). Preserves meaning but varies in chunk size.</p><p><strong>Recursive chunking</strong> — Try to split at large boundaries first (sections), then smaller (paragraphs, sentences). Balances size and semantics.</p><p><strong>Overlap chunking</strong> — Add overlap between chunks to prevent information loss at boundaries. Typically 10-20% overlap.</p><p><strong>Metadata-enriched chunking</strong> — Attach metadata (source, title, section) to each chunk for filtering and context.</p><h3 id="embedding-and-vector-search" tabindex="-1">Embedding and Vector Search <a class="header-anchor" href="#embedding-and-vector-search" aria-label="Permalink to &quot;Embedding and Vector Search&quot;">​</a></h3><p><strong>Embedding models</strong> convert text to dense vectors capturing semantic meaning. Similar concepts have similar vectors.</p><p><strong>Vector similarity search</strong> finds chunks whose embeddings are closest to the query embedding using cosine similarity, dot product, or Euclidean distance.</p><h3 id="hybrid-search" tabindex="-1">Hybrid Search <a class="header-anchor" href="#hybrid-search" aria-label="Permalink to &quot;Hybrid Search&quot;">​</a></h3><p><strong>Keyword search (BM25)</strong> — Matches exact terms; good for specific names, codes, and rare terms.</p><p><strong>Semantic search (vector)</strong> — Matches meaning; good for paraphrased queries and conceptual matches.</p><p><strong>Hybrid</strong> — Combine both with weighted scoring (RRF or linear combination) for best coverage.</p><h3 id="reranking" tabindex="-1">Reranking <a class="header-anchor" href="#reranking" aria-label="Permalink to &quot;Reranking&quot;">​</a></h3><p><strong>Cross-encoder reranking</strong> — A separate model scores each (query, document) pair for relevance. More accurate but slower than initial retrieval.</p><p><strong>Two-phase retrieval:</strong> Vector search retrieves top 50-100 candidates; reranker selects top 5-10.</p><h3 id="evaluation-metrics" tabindex="-1">Evaluation Metrics <a class="header-anchor" href="#evaluation-metrics" aria-label="Permalink to &quot;Evaluation Metrics&quot;">​</a></h3><p><strong>Retrieval metrics:</strong> Recall@k, Precision@k, Mean Reciprocal Rank (MRR), Normalized Discounted Cumulative Gain (NDCG)</p><p><strong>Generation metrics:</strong> Faithfulness (answer grounded in context), relevance (answer addresses query), answer correctness</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Chunk by semantic boundaries</strong> — Split at paragraphs or sections, not arbitrary token counts; preserve complete thoughts and context</li><li><strong>Use hybrid search</strong> — Combine BM25 keyword search with vector semantic search; each catches cases the other misses</li><li><strong>Implement two-phase retrieval</strong> — Fast vector search for candidates, then reranker for precision; balances speed and accuracy</li><li><strong>Enrich chunks with metadata</strong> — Add source document, section title, and date to each chunk; enables filtering and attribution</li><li><strong>Test chunk sizes systematically</strong> — Evaluate different chunk sizes (256, 512, 1024 tokens); optimal size varies by content and model</li><li><strong>Handle context overflow gracefully</strong> — When retrieved context exceeds token budget, truncate by relevance score; never cut mid-sentence</li><li><strong>Implement citation and attribution</strong> — Include source references in responses so users can verify information</li><li><strong>Monitor retrieval quality</strong> — Track which queries return poor results; use feedback to improve chunking, embedding, and retrieval</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using fixed-size chunks only</strong> — Arbitrary token splits break sentences and concepts; always consider semantic boundaries</li><li><strong>Retrieving too few documents</strong> — Insufficient context leads to incomplete answers; retrieve more candidates and let reranking filter</li><li><strong>Retrieving too many documents</strong> — Overstuffing context confuses the model; use reranking to select the most relevant 5-10</li><li><strong>Ignoring document preprocessing</strong> — Raw documents with headers, footers, and formatting noise reduce retrieval quality; clean and normalize</li><li><strong>Not handling multi-language queries</strong> — Different languages need different embeddings or multilingual models; test with Arabic and English</li><li><strong>Forgetting about query expansion</strong> — Single-word or ambiguous queries retrieve poorly; expand with synonyms or reformulate</li><li><strong>Using only vector search</strong> — Pure semantic search misses exact keyword matches; combine with BM25 for comprehensive retrieval</li><li><strong>Not evaluating end-to-end</strong> — Measuring only retrieval accuracy misses generation quality; evaluate the complete pipeline</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Chunking without overlap</strong> — Information at chunk boundaries may be lost; add 10-20% overlap between chunks</li><li><strong>Treating all documents equally</strong> — Some sources are more authoritative; weight trusted sources higher in retrieval</li><li><strong>Ignoring chunk embedding quality</strong> — Poor embeddings produce poor retrieval; choose appropriate embedding models for your domain</li><li><strong>Not updating the knowledge base</strong> — Outdated documents produce outdated responses; implement incremental updates</li><li><strong>Using wrong similarity metric</strong> — Cosine similarity for normalized vectors, dot product for magnitude-sensitive tasks</li><li><strong>Forgetting about metadata filtering</strong> — Without metadata filtering, retrieval returns documents from wrong sources or dates</li><li><strong>Not testing with real queries</strong> — Synthetic test queries don&#39;t represent actual user behavior; test with production query logs</li><li><strong>Over-relying on chunk relevance</strong> — Sometimes the answer requires multiple chunks; implement multi-hop retrieval for complex questions</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Content Type</th><th>Chunking Strategy</th></tr></thead><tbody><tr><td>Technical documentation</td><td>Section-based chunking (512-1024 tokens) with metadata</td></tr><tr><td>FAQ content</td><td>Question-answer pairs as complete chunks</td></tr><tr><td>Legal/contracts</td><td>Paragraph-based chunking with clause metadata</td></tr><tr><td>Code documentation</td><td>Function/class-level chunks with file path metadata</td></tr><tr><td>Blog posts</td><td>Section-based chunks with title and date metadata</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Query Type</th><th>Retrieval Strategy</th></tr></thead><tbody><tr><td>Simple factual</td><td>Vector search + top-3</td></tr><tr><td>Complex reasoning</td><td>Hybrid search + reranking + top-10</td></tr><tr><td>Multi-hop questions</td><td>Iterative retrieval with query decomposition</td></tr><tr><td>Code search</td><td>Hybrid search with code-specific embeddings</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>LangChain RAG Guide: <a href="https://js.langchain.com/docs/tutorials/rag/" target="_blank" rel="noreferrer">https://js.langchain.com/docs/tutorials/rag/</a></li><li>LlamaIndex Documentation: <a href="https://docs.llamaindex.ai/" target="_blank" rel="noreferrer">https://docs.llamaindex.ai/</a></li><li>&quot;Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks&quot; (Lewis et al., 2020)</li><li>Pinecone RAG Guide: <a href="https://www.pinecone.io/learn/retrieval-augmented-generation/" target="_blank" rel="noreferrer">https://www.pinecone.io/learn/retrieval-augmented-generation/</a></li><li>Weaviate RAG Recipes: <a href="https://weaviate.io/developers/weaviate" target="_blank" rel="noreferrer">https://weaviate.io/developers/weaviate</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Supabase + pgvector:</strong> Store embeddings in Supabase with pgvector extension; use for hybrid search with metadata filtering</li><li><strong>Embedding models:</strong> Use OpenAI <code>text-embedding-3-small</code> for cost efficiency or <code>text-embedding-3-large</code> for better accuracy</li><li><strong>Chunk size testing:</strong> Start with 512 tokens, test with 256 and 1024; measure retrieval accuracy at each size</li><li><strong>Arabic content:</strong> Use multilingual embedding models (multilingual-e5-large); Arabic tokenization requires careful chunk size calibration</li><li><strong>Production monitoring:</strong> Log retrieval results, user feedback, and generation quality; use data to continuously improve the pipeline</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',46)])])}const p=t(i,[["render",o]]);export{u as __pageData,p as default};
